p2_example = "Corporate account 'CORP_GLOBAL_TIER1' has an active Master Services Agreement granting a 28% contract discount across enterprise infrastructure. When viewing SKU_SERVER_RACK (base MSRP $4,500.00), the pricing engine confirms SKU entitlement, applies a $1,260.00 contractual discount, and derives an exact net B2B price of $3,240.00."
p2_try_it = "Simulate the B2B Price List Engine, validating that corporate accounts receive contract-specific net pricing while unentitled restricted SKUs are rejected."
p2_code = """import sys
sys.stdout.reconfigure(encoding='utf-8')

class B2BPriceListEngine:
    def __init__(self):
        # Tiered contract discounts per buyer organization
        self.contract_discounts = {
            "CORP_GLOBAL_TIER1": {"discount_pct": 0.28, "restricted_skus": []},
            "CORP_REGIONAL_TIER2": {"discount_pct": 0.15, "restricted_skus": ["SKU_ENTERPRISE_MAINFRAME"]}
        }
        self.base_catalog = {
            "SKU_SERVER_RACK": 4500.0,
            "SKU_NETWORK_SWITCH": 1200.0,
            "SKU_ENTERPRISE_MAINFRAME": 25000.0
        }

    def get_custom_price(self, org_id: str, sku: str) -> dict:
        contract = self.contract_discounts.get(org_id)
        if not contract or sku in contract["restricted_skus"]:
            return {"sku": sku, "entitled": False, "custom_price_usd": None}

        base = self.base_catalog.get(sku, 0.0)
        discount = round(base * contract["discount_pct"], 2)
        final_price = round(base - discount, 2)
        return {
            "org_id": org_id,
            "sku": sku,
            "entitled": True,
            "base_msrp_usd": base,
            "contract_discount_usd": discount,
            "contract_price_usd": final_price
        }

price_engine = B2BPriceListEngine()
price_res = price_engine.get_custom_price("CORP_GLOBAL_TIER1", "SKU_SERVER_RACK")
print(f"B2B Pricing: Org: {price_res['org_id']} | SKU: {price_res['sku']} | Base: ${price_res['base_msrp_usd']} | Discount: -${price_res['contract_discount_usd']} | Net: ${price_res['contract_price_usd']}")
"""
